        return False

    i = 1
    while i < len(text):
        prev_char = text[i-1]

        # Check for underscore followed by lowercase letter (start of new sequence)
        if prev_char == '_' and 'a' <= text[i] <= 'z':
            continue

        # If we encounter an uppercase letter or a non-lowercase, non-underscore character that breaks the pattern
        elif not ('a' <= prev_char <= 'z') and (not ('_' == prev_char) or not ('a' <= text[i] <= 'z')):
             return False

        # If we encounter an uppercase letter anywhere in a sequence of lowercase letters separated by underscores, it's invalid.
        if 'A' <= prev_char <= 'Z':
            return False

        i += 1

